export type ExecutionPlanOperatorIconName = keyof typeof executionPlanOperatorIconData;

type ExecutionPlanOperatorIconLayerKind =
    (typeof executionPlanOperatorIconData)[ExecutionPlanOperatorIconName]["layers"][number]["kind"];

interface ExecutionPlanOperatorIconDefinition {
    readonly viewBox: string;
    readonly layers: ReadonlyArray<{
        readonly kind: ExecutionPlanOperatorIconLayerKind;
        readonly d: string;
    }>;
}

const accentLayerFills: Readonly<
    Record<Exclude<ExecutionPlanOperatorIconLayerKind, "foreground">, string>
> = {
    blue: "var(--vscode-charts-blue, currentColor)",
    purple: "var(--vscode-charts-purple, currentColor)",
    red: "var(--vscode-charts-red, currentColor)",
    green: "var(--vscode-charts-green, currentColor)",
    yellow: "var(--vscode-charts-yellow, currentColor)",
};

function toPascalCase(value: string): string {
    return value
        .split("_")
        .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
        .join("");
}

function createExecutionPlanOperatorIcon(name: ExecutionPlanOperatorIconName): FluentIcon {
    const icon = executionPlanOperatorIconData[name] as ExecutionPlanOperatorIconDefinition;
    const viewBoxParts = icon.viewBox.split(" ");
    const width = viewBoxParts[2];
    const svgPaths = icon.layers
        .map((layer) => {
            const fill =
                layer.kind === "foreground" ? "" : ` fill="${accentLayerFills[layer.kind]}"`;
            return `<path${fill} fill-rule="evenodd" d="${layer.d}" />`;
        })
        .join("");

    return createFluentIcon(`ExecutionPlan${toPascalCase(name)}Icon`, width, svgPaths, {
        color: true,
    });
}

/**
 * Typed registry of Fluent icon components. Consumers can render a component directly, for
 * example: `const Icon = executionPlanOperatorIcons.table_scan; return <Icon />;`.
 */
export const executionPlanOperatorIcons = Object.freeze(
    Object.fromEntries(
        (Object.keys(executionPlanOperatorIconData) as ExecutionPlanOperatorIconName[]).map(
            (name) => [name, createExecutionPlanOperatorIcon(name)],
        ),
    ),
) as Readonly<Record<ExecutionPlanOperatorIconName, FluentIcon>>;

const operatorTypeAliases: Readonly<Record<string, ExecutionPlanOperatorIconName>> = {
    switchStatement: "switch",
    tfp: "predict",
    windowSpool: "table_spool",
    populateQuery: "population_query",
    deleteOperator: "delete",
    ifOperator: "if",
    tsql: "sql",
    keyLookup: "bookmark_lookup",
    groupByApply: "apply",
    localCube: "intrinsic",
};

function camelCaseToSnakeCase(value: string): string {
    return value.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();
}

export function getExecutionPlanOperatorIconName(
    operatorType: string,
): ExecutionPlanOperatorIconName {
    const iconName = operatorTypeAliases[operatorType] ?? camelCaseToSnakeCase(operatorType);
    return Object.prototype.hasOwnProperty.call(executionPlanOperatorIcons, iconName)
        ? (iconName as ExecutionPlanOperatorIconName)
        : "iterator_catch_all";
}

export function getExecutionPlanOperatorIcon(operatorType: string): FluentIcon {
    return executionPlanOperatorIcons[getExecutionPlanOperatorIconName(operatorType)];
}
